import { useEffect, useState } from 'react';

import { findTimeZone } from '@protontech/timezone-support';

import { getSilentApi } from '@proton/shared/lib/api/helpers/customConfig';
import { getLocation } from '@proton/shared/lib/api/vpn';
import { singleCountryTimezoneDatabase } from '@proton/shared/lib/date/singleCountryTimezoneDatabase';
import { manualFindTimeZone } from '@proton/shared/lib/date/timezoneDatabase';
import { getNaiveCountryCode } from '@proton/shared/lib/i18n/helper';
import type { Api, MyLocationResponse } from '@proton/shared/lib/interfaces';

import useApi from './useApi';

const tryTimezone = (tz: string): string | undefined =>
    singleCountryTimezoneDatabase[tz as keyof typeof singleCountryTimezoneDatabase];

const getCountryFromTimezone = () => {
    try {
        const timezone = Intl.DateTimeFormat().resolvedOptions().timeZone;

        if (timezone) {
            return tryTimezone(timezone) || tryTimezone(manualFindTimeZone(timezone) || findTimeZone(timezone).name);
        }
    } catch (e) {
        // undefined
    }
};

export const getCountryFromLanguage = () => {
    const language = navigator.languages.find((language) => /[_-]/.test(language));
    if (language) {
        return getNaiveCountryCode(language);
    }
};

const getStaticState = () => {
    return (getCountryFromTimezone() || getCountryFromLanguage())?.toUpperCase();
};

const getMyCountry = async (api: Api): Promise<string | undefined> => {
    // TODO: Have a non-VPN dedicated API for that purpose
    const value = await api<MyLocationResponse>(getLocation());
    return value?.Country?.toUpperCase();
};

const state: { initialized: boolean; promise: null | Promise<string | undefined>; value: string | undefined } = {
    promise: null,
    value: undefined,
    initialized: false,
};

const getInitialValue = () => {
    if (!state.initialized) {
        state.initialized = true;
        state.value = getStaticState();
    }
    return state.value;
};

const getCountryPromise = (api: Api) => {
    if (state.promise) {
        return state.promise;
    }
    state.promise = getMyCountry(getSilentApi(api))
        .then((value) => {
            state.value = value;
            return value;
        })
        .catch(() => {
            return undefined;
        });
    return state.promise;
};

const useMyCountry = (): [string | undefined, boolean] => {
    const [country, setMyCountry] = useState<string | undefined>(getInitialValue);
    const api = useApi();
    useEffect(() => {
        if (country) {
            return;
        }
        void getCountryPromise(api).then(setMyCountry);
    }, []);
    return [country, !country];
};

export default useMyCountry;
import { getCountryFromLanguage } from './useMyCountry';

describe('getCountryFromLanguage()', () => {
    beforeEach(() => {
        jest.clearAllMocks();
    });

    it('should prioritize languages as given by the browser', () => {
        const mockNavigator = jest.spyOn(window, 'navigator', 'get');
        mockNavigator.mockReturnValue({
            ...window.navigator,
            languages: ['de-DE', 'en-EN'],
        });

        expect(getCountryFromLanguage()).toEqual('de');
    });

    it('should prioritize languages with country code', () => {
        const mockNavigator = jest.spyOn(window, 'navigator', 'get');
        mockNavigator.mockReturnValue({
            ...window.navigator,
            languages: ['fr', 'en_CA'],
        });

        expect(getCountryFromLanguage()).toEqual('ca');
    });

    it('should return undefined when the browser language tags do not have country code', () => {
        const mockNavigator = jest.spyOn(window, 'navigator', 'get');
        mockNavigator.mockReturnValue({
            ...window.navigator,
            languages: ['fr', 'en'],
        });

        expect(getCountryFromLanguage()).toBeUndefined();
    });
});
import type { Ref } from 'react';
import { forwardRef, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';

import type { InputProps } from '@proton/atoms';
import { Input } from '@proton/atoms';
import { useRightToLeft } from '@proton/components/containers/rightToLeft/useRightToLeft';
import useCombinedRefs from '@proton/hooks/useCombinedRefs';
import clsx from '@proton/utils/clsx';

import PhoneCountrySelect from './PhoneCountrySelect';
import {
    getCountries,
    getCountryFromNumber,
    getCursorPosition,
    getExamplePlaceholder,
    getFormattedValue,
    getNumberWithCountryCode,
    getNumberWithoutCountryCode,
    getSafeCountryCallingCode,
    getSpecificCountry,
    getSpecificMaxLength,
    getTrimmedString,
} from './helper';

const usePreviousValue = <T,>(value: T) => {
    const ref = useRef<T>();
    useEffect(() => {
        ref.current = value;
    }, [value]);
    return ref.current;
};

export interface Props extends Omit<InputProps, 'type' | 'value' | 'onChange'> {
    value: string;
    defaultCountry?: string;
    embedded?: boolean;
    onChange: (value: string) => void;
}

const PhoneInputBase = (
    { value: actualValue = '', defaultCountry = 'US', embedded, onChange, onValue, ...rest }: Props,
    ref: Ref<HTMLInputElement>
) => {
    const inputRef = useRef<HTMLInputElement>(null);
    const selectionRef = useRef<number | null>(null);
    const oldSpecificCountryLengthRef = useRef<number>(0);
    const [isCountryCallingCodeMode, setIsCountryCallingCodeMode] = useState(false);
    const [oldCountry, setOldCountry] = useState(defaultCountry);

    const trimmedValue = getTrimmedString(actualValue);
    const previousTrimmedValue = usePreviousValue(trimmedValue);

    const oldCountryCallingCode = getSafeCountryCallingCode(oldCountry);
    const valueWithCountryCallingCode = getNumberWithCountryCode(trimmedValue, oldCountryCallingCode);

    const countryCodeFromValue = getCountryFromNumber(valueWithCountryCallingCode);
    const countryCallingCodeFromValue = getSafeCountryCallingCode(countryCodeFromValue);
    const valueWithoutCountryCallingCode = getNumberWithoutCountryCode(
        valueWithCountryCallingCode,
        countryCallingCodeFromValue
    );
    const [valueCountryCodeSpecific, foundLength] = getSpecificCountry(
        valueWithoutCountryCallingCode,
        countryCallingCodeFromValue,
        oldCountryCallingCode === countryCallingCodeFromValue &&
            valueWithoutCountryCallingCode.length < oldSpecificCountryLengthRef.current
            ? oldCountry
            : countryCodeFromValue
    );

    const placeholder = getNumberWithoutCountryCode(
        getExamplePlaceholder(valueCountryCodeSpecific),
        countryCallingCodeFromValue
    );

    const formattedValue = getFormattedValue(valueWithCountryCallingCode).trim();
    const formattedValueInMode = isCountryCallingCodeMode
        ? formattedValue
        : getNumberWithoutCountryCode(formattedValue, countryCallingCodeFromValue);

    const countryCode = (() => {
        // 1. Going from '' -> '+' === remove country
        const isNullToPlus = previousTrimmedValue === '' && trimmedValue === '+';
        if (isNullToPlus) {
            return '';
        }
        // 2. No country and going from '+' -> '' === add back default country
        const isEmptyCountryToNull = previousTrimmedValue === '+' && trimmedValue === '' && oldCountry === '';
        if (isEmptyCountryToNull) {
            return defaultCountry;
        }
        // 3. Guess country from number
        return valueCountryCodeSpecific || oldCountry;
    })();

    useLayoutEffect(() => {
        if (trimmedValue === '+') {
            setOldCountry('');
            return;
        }
        // Setting from country select
        if (trimmedValue !== '') {
            oldSpecificCountryLengthRef.current = foundLength;
        }
        setOldCountry(countryCode);
    }, [countryCode]);

    useLayoutEffect(() => {
        const inputEl = inputRef.current;
        const selection = selectionRef.current;
        if (!inputEl || selection === null) {
            return;
        }
        const i = getCursorPosition(selection, formattedValueInMode);
        inputEl.selectionStart = i;
        inputEl.selectionEnd = i;
        selectionRef.current = null;
    });

    const countries = useMemo(() => getCountries(), []);
    const selectedValue = countries.find((data) => data.countryCode === countryCode);
    const [isRTL] = useRightToLeft();

    // we force dir="ltr" in all cases, because otherwise phone number will be displayed
    // in reverse in RTL languages, which is not recommended
    return (
        <Input
            {...rest}
            type="tel"
            value={formattedValueInMode}
            ref={useCombinedRefs(inputRef, ref)}
            placeholder={placeholder}
            dir="ltr"
            containerProps={{ dir: 'ltr' }}
            className={clsx([isRTL ? 'text-right' : null])}
            prefix={
                <PhoneCountrySelect
                    embedded={embedded}
                    value={selectedValue}
                    options={countries}
                    onChange={(newSelectedValue) => {
                        oldSpecificCountryLengthRef.current = getSpecificMaxLength(
                            getSafeCountryCallingCode(newSelectedValue.countryCode),
                            newSelectedValue.countryCode
                        );
                        setIsCountryCallingCodeMode(false);
                        setOldCountry(newSelectedValue.countryCode);
                        onChange('');
                    }}
                    onClosed={(isFromSelection) => {
                        if (isFromSelection) {
                            inputRef.current?.focus();
                        }
                    }}
                />
            }
            onChange={(event) => {
                const {
                    target,
                    target: { value: newStringValue },
                } = event;
                selectionRef.current = getTrimmedString(newStringValue.slice(0, target.selectionEnd || 0)).length;
                const newTrimmedValue = getTrimmedString(newStringValue);
                setIsCountryCallingCodeMode(newTrimmedValue[0] === '+');
                const newValue = !newTrimmedValue.length
                    ? ''
                    : getNumberWithCountryCode(newTrimmedValue, countryCallingCodeFromValue);
                onChange(newValue);
            }}
        />
    );
};

const PhoneInput = forwardRef<HTMLInputElement, Props>(PhoneInputBase);
export default PhoneInput;

import { useState } from 'react';

import { fireEvent, render } from '@testing-library/react';

import PhoneInput from './PhoneInput';
import { getCountryFromNumber, getCursorPosition, getSpecificCountry } from './helper';

const Test = ({ initialValue, defaultCountry }: { initialValue: string; defaultCountry?: string }) => {
    const [value, setValue] = useState(initialValue);
    return <PhoneInput defaultCountry={defaultCountry} data-testid="input" value={value} onChange={setValue} />;
};

const getCountry = (el: HTMLElement) => {
    return el.getAttribute('aria-label');
};

jest.mock('./flagSvgs', () => {
    return {
        getFlagSvg: () => true,
    };
});
jest.mock('react-virtualized', () => {
    const ReactVirtualized = jest.requireActual('react-virtualized');
    return {
        ...ReactVirtualized,
        // @ts-ignore
        AutoSizer: ({ children }) => children({ height: 1000, width: 1000 }),
    };
});

interface TestCommands {
    input?: string;
    select?: string;
    expectation: { value: string; country: string | null };
}

const runTest = (testCommands: TestCommands[]) => {
    const { getByTestId, getByRole, getByPlaceholderText, getByTitle } = render(
        <Test initialValue="" defaultCountry="US" />
    );

    const inputEl = getByTestId('input') as HTMLInputElement;
    const buttonEl = getByRole('button') as HTMLButtonElement;

    testCommands.forEach(({ input, select, expectation: { value, country } }) => {
        if (select !== undefined) {
            fireEvent.click(buttonEl);
            const searchEl = getByPlaceholderText('Country');
            fireEvent.change(searchEl, { target: { value: select } });
            const rowEl = getByTitle(select);
            fireEvent.click(rowEl);
        }
        if (input !== undefined) {
            fireEvent.change(inputEl, { target: { value: input } });
        }
        expect(inputEl.value).toBe(value);
        expect(getCountry(buttonEl)).toBe(country);
    });
};

describe('PhoneInput', () => {
    it('should format input', () => {
        const spy = jest.fn();
        const { getByTestId, getByRole, rerender } = render(
            <PhoneInput value="+41781234567" data-testid="input" onChange={spy} />
        );
        const input = getByTestId('input') as HTMLInputElement;
        const button = getByRole('button') as HTMLButtonElement;
        expect(input.value).toBe('78 123 45 67');
        expect(getCountry(button)).toBe('Switzerland');
        rerender(<PhoneInput data-testid="input" value="+410782354666" onChange={spy} />);
        expect(input.value).toBe('78 235 46 66');
        expect(getCountry(button)).toBe('Switzerland');
        rerender(<PhoneInput data-testid="input" value="+1613123" onChange={spy} />);
        expect(input.value).toBe('613 123');
        expect(getCountry(button)).toBe('Canada');
        rerender(<PhoneInput data-testid="input" value="+1631123" onChange={spy} />);
        expect(input.value).toBe('631 123');
        expect(getCountry(button)).toBe('United States');
    });

    it('format as user enters text', () => {
        runTest([
            { input: '631', expectation: { value: '631', country: 'United States' } },
            { input: '6311', expectation: { value: '631 1', country: 'United States' } },
            { input: '631', expectation: { value: '631', country: 'United States' } },
            { input: '613', expectation: { value: '613', country: 'Canada' } },
            { input: '6131', expectation: { value: '613 1', country: 'Canada' } },
            { input: '61', expectation: { value: '61', country: 'Canada' } },
            { input: '', expectation: { value: '', country: 'Canada' } },
            { input: '6', expectation: { value: '6', country: 'Canada' } },
            { input: '63', expectation: { value: '63', country: 'Canada' } },
            { input: '631', expectation: { value: '631', country: 'United States' } },
        ]);
    });

    it('change country if entering with country calling code', () => {
        runTest([
            { input: '', expectation: { value: '', country: 'United States' } },
            { input: '+41', expectation: { value: '+41', country: 'Switzerland' } },
            { input: '+417', expectation: { value: '+41 7', country: 'Switzerland' } },
            { input: '+41781', expectation: { value: '+41 78 1', country: 'Switzerland' } },
            { input: '', expectation: { value: '', country: 'Switzerland' } },
            { input: '78', expectation: { value: '78', country: 'Switzerland' } },
            { input: '781', expectation: { value: '78 1', country: 'Switzerland' } },
        ]);
    });

    it('change country selecting from dropdown', () => {
        runTest([
            { input: '', expectation: { value: '', country: 'United States' } },
            { select: 'Canada', expectation: { value: '', country: 'Canada' } },
            { input: '6', expectation: { value: '6', country: 'Canada' } },
            { input: '61', expectation: { value: '61', country: 'Canada' } },
            { input: '613', expectation: { value: '613', country: 'Canada' } },
            { select: 'Bahamas', expectation: { value: '', country: 'Bahamas' } },
            { input: '6', expectation: { value: '6', country: 'Bahamas' } },
            { input: '61', expectation: { value: '61', country: 'Bahamas' } },
            { input: '613', expectation: { value: '613', country: 'Canada' } },
            { input: '631', expectation: { value: '631', country: 'United States' } },
            { select: 'Canada', expectation: { value: '', country: 'Canada' } },
        ]);
    });

    it('reset and remember country', () => {
        runTest([
            { input: '', expectation: { value: '', country: 'United States' } },
            { input: '+', expectation: { value: '+', country: null } },
            { input: '+4', expectation: { value: '+4', country: null } },
            { input: '+41', expectation: { value: '+41', country: 'Switzerland' } },
            { input: '', expectation: { value: '', country: 'Switzerland' } },
            { input: '+', expectation: { value: '+', country: null } },
        ]);
    });

    it('should get a country from a number', () => {
        expect(getCountryFromNumber('+')).toEqual('');
        expect(getCountryFromNumber('+1')).toEqual('US');
        expect(getCountryFromNumber('+11')).toEqual('US');
        expect(getCountryFromNumber('+111')).toEqual('US');
        expect(getCountryFromNumber('+12')).toEqual('US');
        expect(getCountryFromNumber('3')).toEqual('');
        expect(getCountryFromNumber('2')).toEqual('');
        expect(getCountryFromNumber('1')).toEqual('');
        expect(getCountryFromNumber('+41')).toEqual('CH');
        expect(getCountryFromNumber('+411')).toEqual('CH');
        expect(getCountryFromNumber('+411')).toEqual('CH');
        expect(getCountryFromNumber('+42')).toEqual('');
        expect(getCountryFromNumber('+320')).toEqual('BE');
    });

    it('should get a more specific country from a number', () => {
        expect(getSpecificCountry('', '1', 'US')).toEqual(['US', 0]);
        expect(getSpecificCountry('613', '1', 'US')).toEqual(['CA', 3]);
        expect(getSpecificCountry('631', '1', 'US')).toEqual(['US', 0]);
        expect(getSpecificCountry('787', '1', 'US')).toEqual(['PR', 3]);
        expect(getSpecificCountry('7', '7', 'RU')).toEqual(['KZ', 1]);
        expect(getSpecificCountry('', '7', 'KZ')).toEqual(['KZ', 0]);
    });

    it('should get cursor at position', () => {
        [
            { digit: 1, value: '1', expectation: 1 },
            { digit: 2, value: '1', expectation: 1 },
            { digit: 0, value: '1----2', expectation: 0 },
            { digit: 0, value: '--1--', expectation: 1 },
            { digit: 0, value: '--1', expectation: 1 },
            { digit: 0, value: '--12', expectation: 1 },
            { digit: 0, value: '--1-2-', expectation: 1 },
            { digit: 1, value: '--1-2-', expectation: 3 },
            { digit: 1, value: '--1----2', expectation: 6 },
            { digit: 0, value: '--1----2', expectation: 1 },
        ].forEach(({ digit, value, expectation }) => {
            expect(getCursorPosition(digit, value)).toEqual(expectation);
        });
    });

    it('should format input for CH', () => {
        const { getByTestId } = render(<Test defaultCountry="CH" initialValue="" data-testid="input" />);
        const input = getByTestId('input') as HTMLInputElement;
        expect(input.value).toBe('');
        fireEvent.change(input, { target: { value: '1' } });
        expect(input.value).toBe('1');
    });

    it('should format input for US', () => {
        const { getByTestId } = render(<Test defaultCountry="US" initialValue="" data-testid="input" />);
        const input = getByTestId('input') as HTMLInputElement;
        expect(input.value).toBe('');
        fireEvent.change(input, { target: { value: '1' } });
        expect(input.value).toBe('1');
    });
});
